import {renderRejection} from './cooling-rejection.js';
import {chillerBalance, operatingPoint, heatReuse, decisionFeedback} from './heat-rejection-model.js';
const n = (value, digits = 2) => Number(value.toFixed(digits)).toLocaleString('en-US');
const arrow = '<span class="h-arrow" aria-hidden="true">→</span>';
const stat = (value, label, extra = '') => `<div class="h-stat ${extra}"><strong>${value}</strong><span>${label}</span></div>`;
const node = (title, detail = '', extra = '') => `<div class="h-node ${extra}"><b>${title}</b>${detail ? `<span>${detail}</span>` : ''}</div>`;
const strip = text => `<p class="h-strip">${text}</p>`;
const stack = content => `<div class="h-stack">${content}</div>`;
const input = text => `<p class="h-input">${text}</p>`;
const route = (middle, sink, detail = '') => `<div class="h-route" aria-label="Heat path from rack through outdoor plant"><span>Rack heat</span>${arrow}<span>Facility water</span>${arrow}<span>${middle}</span>${arrow}<span>${sink}</span></div>${detail ? input(detail) : ''}`;
const panel = (title, body, extra = '') => `<section class="h-panel ${extra}"><h2>${title}</h2>${body}</section>`;
const legacy = (id, state, compact, label) => `<div class="h-legacy"><svg role="img" aria-label="${label}" viewBox="${compact ? '0 0 372 580' : '0 0 1160 420'}">${renderRejection(id, compact, state)}</svg></div>`;
function powerBar(p) {
  return `<div class="h-power"><div class="h-power-header"><span>Site electricity</span><b class="${p.electricalFits ? '' : 'h-warning'}">${n(p.totalMW)} / 10 MW</b></div><div class="h-power-track" role="img" aria-label="Computing ${n(p.requestedITMW)}, cooling ${n(p.coolingMW)}, other 0.4 MW: ${n(p.totalMW)} MW against a 10 MW limit"><span class="h-it" style="width:${p.requestedITMW / 11 * 100}%"></span><span class="h-cooling" style="width:${p.coolingMW / 11 * 100}%"></span><span class="h-other" style="width:${p.otherMW / 11 * 100}%"></span><i style="left:${10 / 11 * 100}%"><em>10 MW limit</em></i></div><div class="h-legend"><span><i class="h-it"></i>Computing ${n(p.requestedITMW)} MW</span><span><i class="h-cooling"></i>Cooling ${n(p.coolingMW)} MW</span><span><i class="h-other"></i>Other 0.4 MW</span></div></div>`;
}
function temperaturePath(title, points, step, fail) {
  return `<section class="h-temperature-path"><h2>${title}</h2><div class="h-temperature-stages">${points.map(([value, label, gap, equipment], i) => `<div class="h-temperature-stage ${i > step ? 'h-unrevealed' : ''}" ${i <= step ? `data-approach-step="${i}"` : 'aria-hidden="true"'}>${i ? `<span class="h-gap">${equipment} +${gap}°C</span>` : ''}<div class="h-temperature ${i === points.length - 1 && step >= i ? fail ? 'h-fail' : 'h-pass' : ''}"><b>${value}°C</b><span>${label}</span></div></div>`).join('')}</div></section>`;
}
function reuseChart(hours, compact) {
  const width = compact ? 520 : 920, left = compact ? 65 : 90, plotWidth = compact ? 420 : 790, top = 35, height = 190, bottom = top + height;
  const acceptedWidth = plotWidth * hours / 24;
  return `<svg class="h-reuse-plot" role="img" aria-label="4 MW heat available all day. Customer accepts 2 MW for ${hours} hours. Shaded overlap is accepted heat; the remaining heat goes outdoors." viewBox="0 0 ${width} 280"><rect x="${left}" y="${top}" width="${plotWidth}" height="${height}" class="h-reuse-available"/><rect x="${left}" y="${top + height / 2}" width="${acceptedWidth}" height="${height / 2}" class="h-reuse-accepted"/><path d="M${left} ${top}V${bottom}H${left + plotWidth}" class="h-chart-axis"/><path d="M${left} ${top + height / 2}H${left + plotWidth}" class="h-chart-grid"/><text x="${left - 15}" y="${top + 8}" text-anchor="end">4 MW</text><text x="${left - 15}" y="${top + height / 2 + 8}" text-anchor="end">2 MW</text><text x="${left - 15}" y="${bottom + 6}" text-anchor="end">0</text>${[0, 6, 12, 24].map(t => `<text x="${left + plotWidth * t / 24}" y="${bottom + 35}" text-anchor="${t === 0 ? 'start' : t === 24 ? 'end' : 'middle'}">${t} h</text>`).join('')}<text x="${left + plotWidth * .56}" y="${top + 62}" text-anchor="middle">Heat still goes outdoors</text>${hours ? `<text class="h-chart-light" x="${left + acceptedWidth / 2}" y="${bottom - 35}" text-anchor="middle">Accepted</text>` : ''}</svg>`;
}
export function heatRejectionVisual(id, state, compact = false) {
  if (id === 'heat-rejection-purpose') return stack(`${input('Continue the heat path from the rack.')}<div class="h-flow">${node('Collect','Chips warm rack coolant','h-water')}${arrow}${node('Carry','A separate facility loop','h-water')}${arrow}${node('Release','Outdoor equipment transfers heat','h-outdoors')}</div><div class="h-heat-line">Heat keeps moving until it reaches the environment.</div>${strip('Changing the outdoor plant changes its electricity and water needs.')}`);
  if (id === 'abilene-cooling') return `<div class="h-case"><figure><img src="../assets/references/distribution-abilene-data-halls.jpg" alt="Oracle aerial photograph of the original Abilene data-center campus and its data halls."><figcaption><a href="https://www.oracle.com/data-centers/" target="_blank" rel="noopener">Oracle · Abilene aerial · July 15, 2026</a></figcaption></figure><div class="h-case-copy"><p class="h-date">Crusoe design account · August 2025</p><div class="h-vertical">${node('Facility water','Circulates and carries heat')}${arrow}${node('Air-cooled chiller','Uses electricity to move heat')}${arrow}${node('Outdoor air','Receives the heat')}</div><p class="h-credit"><a href="https://www.crusoe.ai/resources/blog/an-inside-look-at-the-abilene-ai-data-center" target="_blank" rel="noopener">Non-evaporative rejection. Fill and maintenance still use water.</a></p></div></div>`;
  if (id === 'rejection') return legacy('rejection', state, compact, 'Dry coil and evaporative tower heat and water paths');
  if (id === 'weather') {
    const humid = state.humidity === 'humid', wet = humid ? 28 : 22;
    return stack(`${route('Outdoor cooler', 'Air')}<div class="h-two">${panel('Ordinary air temperature', `${stat('35°C','Dry bulb')}<div class="h-thermometer"><span style="height:87.5%"></span></div>`)}${panel('Temperature of a wetted sensor', `${stat(`${wet}°C`,'Wet bulb')}<div class="h-thermometer h-wet"><span style="height:${wet / 40 * 100}%"></span></div>`)}</div><p class="h-cause">${humid ? 'Less water evaporates. The wetted sensor stays warmer.' : 'Water evaporates into dry air. The wetted sensor cools more.'}</p>${strip('Real coolers need a temperature gap above the relevant air condition.')}`);
  }
  if (id === 'approach-outdoors') {
    const wb = state.humidity === 'humid' ? 28 : 22, step = state.interfaceStep;
    return stack(`${input('Illustrative temperatures and fixed gaps · rack supply must be 35°C or cooler')}${temperaturePath('Dry cooler', [[35,'Outdoor air',0],[40,'Facility supply',5,'Dry cooler'],[45,'Rack supply',5,'CDU']], step, true)}${temperaturePath('Wet tower', [[wb,'Outdoor wet bulb',0],[wb+3,'Tower water',3,'Tower'],[wb+8,'Facility supply',5,'Exchanger'],[wb+13,'Rack supply',5,'CDU']], step, wb+13>35)}${strip(step < 3 ? 'Follow each interface to the rack. Each gap changes the supply temperature.' : wb === 22 ? 'The wet route just meets 35°C. Now switch to humid air.' : 'Humid air raises rack supply to 41°C. This route needs another solution.')}`);
  }
  if (id === 'chiller-balance') {
    const m = chillerBalance();
    return stack(`${input('A separate steady chiller example · pumps and fans excluded')}<div class="h-chiller">${stat('10 MW','Heat collected from the cold side')}${arrow}<div class="h-machine"><div class="h-work">+ 2 MW <span>compressor electricity</span><span aria-hidden="true">↓</span></div>${node('Chiller','Moves heat to a warmer sink')}</div>${arrow}${stat(`${n(m.condenserMW)} MW`,'Heat released at the hot side','h-warm')}</div>${strip('Refrigeration can deliver colder coolant when direct cooling cannot.')}`);
  }
  if (id === 'cooling-cop') return stack(`${input('Whole cooling plant · pumps and fans included')}<div class="h-cop-picture"><div><div class="h-energy-blocks h-electricity"><i></i></div><p>1 unit of electricity</p></div>${arrow}<div><div class="h-energy-blocks">${'<i></i>'.repeat(4)}</div><p>4 units of heat moved</p></div></div><div class="h-cop-caption">Coefficient of performance: <b>COP 4</b></div>${strip('A higher COP means less electricity for the same cooling job.')}`);
  if (id === 'plant-options') return stack(`${route('Outdoor cooler', 'Air')}<div class="h-bypass"><div class="h-bypass-active">${node('Warm facility water','Arrives from the racks')}${arrow}${node('Outdoor cooling path','Weather allows direct heat transfer')}${arrow}${node('Cool facility water','Returns to the racks')}</div><div class="h-resting">Compressor can rest <span>Fans and pumps keep working</span></div></div>${strip('This is economizer operation. Available modes depend on weather and supply temperature.')}`);
  if (id === 'adiabatic-assist') return stack(`${input('Follow outdoor air toward the coil.')}<div class="h-flow">${node('Warm outdoor air','More help when the air is dry','h-outdoors')}${arrow}${node('Wetted pads','Water evaporates and cools the air','h-water')}${arrow}${node('Dry coil','Cooler air takes heat from liquid')}</div><div class="h-separate"><span>Pad water evaporates</span><span>Process liquid stays inside the coil</span></div>${strip('This adiabatic assist consumes water. Humid weather limits the benefit.')}`);
  if (id === 'hot-hour') {
    const p = operatingPoint({condition:state.condition, requestedITMW:state.requestedITMW});
    return stack(`${input('Illustrative 10 MW site · all cooling electricity included')}${route('Cooling plant', 'Outdoors')}${powerBar(p)}<div class="h-capacity-line"><span class="${p.thermalFits ? 'h-pass-text' : 'h-warning'}">Heat removal: ${n(p.requestedITMW)} of ${n(p.thermalMW)} MW</span><b class="${p.electricalFits ? 'h-pass-text' : 'h-warning'}">${p.electricalFits ? 'Both limits fit' : 'Electricity exceeds the limit'}</b></div>${strip(state.condition === 'cool' ? 'Before switching to hot weather, predict which part of the bar will grow.' : p.electricalFits ? 'Lower computing demand also lowers cooling electricity.' : 'There is enough heat-removal capacity. Lower computing power to fit site electricity.')}`);
  }
  if (id === 'weather-bins') return stack(`${input('Same site · proposed 8 MW computing held all day')}<div class="h-day-chart" role="img" aria-label="Twelve cool hours require 9.4 MW. Twelve hot hours require 10.4 MW, above the 10 MW site limit. The 9.9 MW average hides the exceedance."><div class="h-day-limit">10 MW supply</div><div class="h-day-column"><div style="height:78.33%"><b>9.4 MW</b><span>Fits</span></div><p>12 cool hours</p></div><div class="h-day-column h-hot-column"><div style="height:86.67%"><b>10.4 MW</b><span>Too much</span></div><p>12 hot hours</p></div></div><p class="h-cause">The 9.9 MW average fits. The hot hours do not.</p>${strip('Reduce demand during those hours or change the qualified cooling path.')}`);
  if (id === 'closed-loop-water') {
    const tower = state.closedSink === 'tower';
    return stack(`${route('Chiller', tower ? 'Tower → air' : 'Outdoor air')}<div class="h-flow">${node('Closed rack loop','Coolant recirculates','h-water')}${arrow}${node('Closed facility loop','Transfers heat through the chiller','h-water')}${arrow}${node(tower ? 'Separate tower circuit' : 'Air-cooled condenser', tower ? 'Water evaporates outdoors' : 'Air receives the heat','h-outdoors')}</div>${strip(tower ? 'The rack loop stays closed while the tower needs replacement water.' : 'This heat-rejection path avoids intentional evaporation. Fill and maintenance still use water.')}`);
  }
  if (id === 'water-ledger') {
    const stage = state.mineralStage, refill = stage === 'refill', purge = stage === 'purge';
    const dots = Array.from({length:refill ? 7 : purge ? 4 : 10},(_,i)=>`<i style="left:${12+(i*23)%77}%;bottom:${12+(i*17)%48}%"></i>`).join('');
    return stack(`<div class="h-minerals" data-mineral-stage="${stage}"><div class="h-water-event">${refill ? 'Fresh makeup water enters ↓' : purge ? 'Some concentrated water is discharged ↓' : 'Water evaporates and carries heat upward ↑'}</div><div class="h-basin"><div class="h-basin-water" style="height:${refill ? 78 : purge ? 19.2 : 48}%">${dots}</div><span>Dissolved minerals</span></div><p>${refill ? 'Replacement water restores the level and dilutes the remaining minerals.' : purge ? 'This discharge is called blowdown. It removes some of the minerals.' : 'The minerals remain as the water level falls. Their concentration rises.'}</p></div>${strip('Makeup replaces water lost through evaporation and discharge.')}`);
  }
  if (id === 'water-metrics') return stack(`${input('Illustrative day · no drift, leaks or storage change')}<div class="h-water-ledger"><div>${stat('125 m³','Intake into the site')}</div>${arrow}<div class="h-water-outputs">${stat('100 m³','Evaporates','h-warm')}${stat('25 m³',state.returnKnown ? 'Discharged and returned to the same basin' : 'Discharged; destination unknown')}</div></div><div class="h-verdict">${stat(state.returnKnown ? '100 m³' : 'Unresolved','Consumption after accounting for return water')}</div>${strip(state.returnKnown ? 'The verified return reduces counted consumption, while intake stays the same.' : 'Without return evidence, we cannot assume a return-water credit.')}`);
  if (id === 'heat-reuse') {
    const m = heatReuse({receiverHours:state.receiverHours});
    return stack(`${input('Separate example · 4 MW available continuously · customer accepts up to 2 MW')}${reuseChart(state.receiverHours, compact)}<div class="h-reuse-caption"><span>Matching temperature</span><span>Matching customer hours</span><span>Outdoor rejection available</span></div>${strip(m.acceptedMWh ? 'Only the overlap is reused. Everything else still needs a heat destination.' : 'The customer is closed. All of the heat must go to another destination.')}`);
  }
  if (id === 'water-restriction') return stack(`${input('Return to the hot-hour site example')}<div class="h-two">${panel('Tower path',`${node('Makeup water unavailable','Sustained tower operation unavailable','h-off')}`)}${panel('Air-cooled alternate',`${node('Qualified for this hot hour','8.5 MW heat-removal capacity')}`)}</div>${route('Surviving plant','Outdoors')}${strip('The alternate still draws electricity from the same 10 MW site supply.')}`);
  if (id === 'heat-rejection-check') {
    const feedback = decisionFeedback(state.choice);
    return `<div class="h-check"><div class="h-brief"><h2>Hot day. No tower makeup.</h2><p>Computing: <b>8 MW</b></p><p>Air-cooled alternate: <b>enough heat-removal capacity</b></p><p>At that load, total electricity: <b class="h-warning">10.4 MW / 10 MW available</b></p><p>Which path survives? What must change?</p></div><div class="h-check-answer">${state.revealed ? `<div class="h-feedback ${feedback.correct ? 'h-good' : 'h-bad'}"><h2>${feedback.correct ? 'Both limits pass.' : 'Recheck the complete path.'}</h2><p>${feedback.text}</p></div>` : `<div class="h-answer-choices">${[['full','Air-cooled alternate; keep full computing power'],['reduce','Air-cooled alternate; lower computing power'],['tower','Keep the tower; the rack loop is closed']].map(([key,label])=>`<button type="button" data-plan="${key}" aria-pressed="${state.choice===key}">${label}</button>`).join('')}</div>`}<button type="button" id="decision-reveal" ${!state.choice ? 'disabled' : ''}>${state.revealed ? 'Try another plan' : 'Explain this plan'}</button></div></div>`;
  }
  throw new RangeError(`Unknown heat-rejection scene: ${id}`);
}
